import React, { useState, useEffect } from 'react';

const API_URL = 'https://merimonial-backend.onrender.com';

const SubAdminCard = () => {
  const [stats, setStats] = useState({ total: 0, active: 0, suspended: 0 });
  const [avatars, setAvatars] = useState({ total: [], active: [], suspended: [] });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      setLoading(true);
      try {
        const token = localStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}` };

        const [totalRes, activeRes, suspendedRes] = await Promise.all([
          fetch(`${API_URL}/api/sub-admin/filter/sub-admin/active?status=all`, { headers }),
          fetch(`${API_URL}/api/sub-admin/filter/sub-admin/active?status=active`, { headers }),
          fetch(`${API_URL}/api/sub-admin/filter/sub-admin/active?status=suspended`, { headers }),
        ]);

        const [totalData, activeData, suspendedData] = await Promise.all([
          totalRes.json(),
          activeRes.json(),
          suspendedRes.json(),
        ]);

        setStats({
          total: totalData?.totalCount ?? totalData?.data?.length ?? 0,
          active: activeData?.totalCount ?? activeData?.data?.length ?? 0,
          suspended: suspendedData?.totalCount ?? suspendedData?.data?.length ?? 0,
        });

        setAvatars({
          total: (totalData?.data || []).slice(0, 5),
          active: (activeData?.data || []).slice(0, 5),
          suspended: (suspendedData?.data || []).slice(0, 5),
        });
      } catch (err) {
        console.error('Failed to fetch sub-admin stats:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  const cards = [
    {
      title: 'Total Sub Admin',
      count: stats.total,
      users: avatars.total,
      ring: 'ring-white',
      border: 'border-gray-300',
    },
    {
      title: 'Active Sub Admin',
      count: stats.active,
      users: avatars.active,
      ring: 'ring-green-500',
      border: 'border-green-400',
    },
    {
      title: 'Suspended Sub Admin',
      count: stats.suspended,
      users: avatars.suspended,
      ring: 'ring-red-500',
      border: 'border-red-400',
    },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
      {cards.map((card) => (
        <div key={card.title} className={`border ${card.border} rounded-xl p-4 shadow bg-white text-center`}>
          <h2 className="font-semibold mb-2">{card.title}</h2>
          <div className="flex justify-center -space-x-2 overflow-hidden mb-2 min-h-[40px]">
            {loading ? (
              <div className="flex gap-1 justify-center">
                {[...Array(5)].map((_, i) => (
                  <div key={i} className="w-10 h-10 rounded-full bg-gray-200 animate-pulse" />
                ))}
              </div>
            ) : card.users.length > 0 ? (
              card.users.map((user, idx) => (
                <img
                  key={idx}
                  src={user.profileImage || `https://ui-avatars.com/api/?name=${user.firstName}+${user.lastName}&background=random`}
                  alt={user.firstName}
                  className={`inline-block h-10 w-10 rounded-full ring-2 ${card.ring} object-cover`}
                />
              ))
            ) : (
              <div className="text-xs text-gray-400 flex items-center">No data</div>
            )}
          </div>
          <p className="text-2xl font-bold">
            {loading ? <span className="text-gray-300 animate-pulse">--</span> : card.count}
          </p>
        </div>
      ))}
    </div>
  );
};

export default SubAdminCard;